// Sub component for testing component hierarchy

import {
  Component,
  Input,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Inject,
} from '@angular/core'
import { sequences } from 'cerebral'
import { CerebralComponent } from '../src/CerebralComponent'
import { AppService } from '../src/AppService'
import { connect } from '../src/connect'

/**
 * Connected test sub-component
 */
@Component({
  selector: 'test-sub-component',
  template: `
    <div id="subComp">
      <div id="name">{{ subCompObj.name }}</div>
      <div id="freq">{{ subCompObj.freq }}</div>
      <div id="increaseFreq" (click)="increaseFreq()">Increase Freq</div>
      <div id="changeName" (click)="changeSubCompName()">Change Name</div>
    </div>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
  standalone: true,
})
@connect({
  increaseFreq: sequences`increaseFreq`,
  changeSubCompName: sequences`changeSubCompName`,
})
export class TestSubComponent extends CerebralComponent {
  @Input() subCompObj: any

  constructor(
    @Inject(ChangeDetectorRef) cdr: ChangeDetectorRef,
    @Inject(AppService) appService: AppService
  ) {
    super(cdr, appService)
  }
}
